import{_ as n,o as i,c as a,ai as e}from"./chunks/framework.Ai2o9gNv.js";const p="/assets/image-20240807232620032.CuywcbMU.png",l="/assets/image-20240807234518067.DWgZlK1G.png",t="/assets/image-20240807234838624.Bxc0G06-.png",r="/assets/PixPin_2024-08-07_23-55-31.DulPZZSS.gif",h="/assets/PixPin_2024-08-08_00-05-31.Dv3mOaDt.gif",k="/assets/PixPin_2024-08-08_00-14-16.BAXmFyXe.gif",E="/assets/image-20240808003957736.C6c1YFwr.png",u=JSON.parse('{"title":"HarmonyOS Next V2 状态管理AppStorageV2和PersistenceV2","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 AppStorageV2和PersistenceV2/AppStorageV2和PersistenceV2.md","filePath":"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 AppStorageV2和PersistenceV2/AppStorageV2和PersistenceV2.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next V2 状态管理AppStorageV2和PersistenceV2\\n\\n## 前言\\n\\n在`HarmonyOS`应用开发过程中，我们已经学习过了不少关于状态管理相关的技术，如 \\n\\n- `@ObservedV2`装饰器和`@Trace`装饰器：类属性变化观测\\n- `@ComponentV2`装饰器：自定义组件\\n- `@Local`装饰器：组件内部状态\\n- `@Param`：组件外部输入\\n- `@Once`：初始化同步一次\\n- `@Event`装饰器：组件输出\\n- `@Monitor`装饰器：状态变量修改监听\\n- `@Provider`装饰器和`@Consumer`装饰器：跨组件层级双向同步（没有讲过）\\n- `@Computed`装饰器：计算属性\\n- `@Type`装饰器：标记类属性的类型\\n\\n以上状态管理技术，都是围绕着组件内部本身的。现在要讲解的`AppStorageV2`和`PersistenceV2`可以理解为应用/全局的状态管理技术。\\n\\n1. `AppStorageV2`是应用级别的数据管理技术，跨组件、跨页面。只要是主线程之内的UIAbility实例都可以共享数据。但是退出应用数\\n\\n   据会自动销毁。\\n\\n2. `PersistenceV2`是应用级别的数据持久化技术，数据是直接存在设备磁盘上的，退出重新进入后，数据还存在\\n\\n\\n\\n\\n\\n## AppStorageV2\\n\\n实际开发中，我们避免不了需要将数据实时共享在多个页面或者组件中，如个人信息，那么便可以考虑将数据存放在`AppStorageV2`中。\\n\\n`AppStorageV2`是应用级别的数据管理技术，跨组件、跨页面。只要是主线程之内的UIAbility实例都可以共享数据。但是退出应用数据会自动\\n\\n销毁。\\n\\n![image-20240807232620032](readme.assets/image-20240807232620032.png)\\n\\n## AppStorageV2核心API\\n\\n| 名称    | 作用                        |\\n| ------- | --------------------------- |\\n| connect | 创建或获取储存的数据        |\\n| remove  | 删除指定key的储存数据       |\\n| keys    | 返回所有AppStorageV2中的key |\\n\\n### connect\\n\\n创建或获取储存的数据  \\n\\n| connect | 说明                                                         |\\n| ------- | ------------------------------------------------------------ |\\n| 参数    | type：指定的类型，若未指定key，则使用type的name作为key；<br />keyOrDefaultCreater：指定的key，或者是默认数据的构造器；<br />defaultCreator：默认数据的构造器。 |\\n| 返回值  | 创建或获取数据成功时，返回数据；否则返回undefined。          |\\n\\n**示例代码**:\\n\\n**Index.ets**\\n\\n```typescript\\nimport { AppStorageV2, router } from \'@kit.ArkUI\'\\n\\n\\n@ObservedV2\\nexport class Person {\\n  @Trace\\n  age: number = 10\\n}\\n\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local person: Person = AppStorageV2.connect(Person, () => new Person)!\\n\\n  build() {\\n    Column() {\\n      Text(\\"A页面\\")\\n      // 预览器会失效\\n      Button(`年龄:${this.person.age}`)\\n        .onClick(() => {\\n          this.person.age++\\n        })\\n\\n\\n      Button(\\"跳转到B页面\\")\\n        .onClick(() => {\\n          router.pushUrl({\\n            url: \\"pages/Index2\\"\\n          })\\n        })\\n    }\\n  }\\n}\\n```\\n\\n**代码解释**：\\n\\n`@Local person: Person = AppStorageV2.connect(Person, () => new Person)!` 创建或者读取 `key` 为`Person`的数据。\\n\\n`@Local` 是用来修饰person，表示person是一个状态，状态改变时，会引起UI的更新\\n\\n`.connect(Person,..`    `Person`，作为`connect`方法的第一个参数，表示 `Person`类型\\n\\n`.connect(Person, () => new Person)!`，由于`connect`中没有传入特定的`key`，那么便将`Person.name`视作`key` 。相当于\\n\\n`.connect(Person, Person.name,() => new Person)!` 或者\\n\\n`.connect(Person,\'Person\',() => new Person)!` \\n\\n![image-20240807234518067](readme.assets/image-20240807234518067.png)\\n\\n同时，因为有 `() => new Person`的作用，那么初始的数据也有了。\\n\\n最后，因为 `connect`的返回值可能为空，因此在最后加上一个 `！`表示非空断言\\n\\n**值得注意的是**，以上代码在预览器上显示时，会得出 `age = undefined`的结果，所以需要在模拟器上测试\\n\\n![image-20240807234838624](readme.assets/image-20240807234838624.png)\\n\\n最后，如果你在A页面使用以上代码，修改了 age，那么B页面上也使用了age。那么便可以看到两个页面的数据是一样的。\\n\\n**Index.ets**\\n\\n```typescript\\nimport { Person } from \\"./Index\\";\\nimport { AppStorageV2 } from \'@kit.ArkUI\';\\n\\n@Entry\\n@ComponentV2\\nstruct Index2 {\\n  @Local person: Person = AppStorageV2.connect(Person, () => new Person)!\\n\\n  build() {\\n    Column() {\\n      Text(\\"B页面\\")\\n      Button(`age：${this.person.age}`)\\n    }\\n  }\\n}\\n```\\n\\n**结果**\\n\\n![PixPin_2024-08-07_23-55-31](readme.assets/PixPin_2024-08-07_23-55-31.gif)\\n\\n### remove\\n\\n删除指定key的储存数据\\n\\n| remove | 说明                                                         |\\n| ------ | ------------------------------------------------------------ |\\n| 参数   | keyOrType：需要删除的key；如果指定的是type类型，删除的key为type的name。 |\\n| 返回值 | 无。                                                         |\\n\\n比如：`AppStorageV2.remove(Person)`    其实是等价于\\n\\n `AppStorageV2.remove(Person.name)` 或者 `AppStorageV2.remove(\'Person\')`\\n\\n**示例代码：**\\n\\n```typescript\\nimport { AppStorageV2, router } from \'@kit.ArkUI\'\\n\\n\\n@ObservedV2\\nexport class Person {\\n  @Trace\\n  age: number = 10\\n}\\n\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local person: Person = AppStorageV2.connect(Person, () => new Person)!\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Text(\\"A页面\\")\\n      // 预览器会失效\\n      Button(`年龄:${this.person.age}`)\\n        .onClick(() => {\\n          this.person.age++\\n        })\\n\\n\\n      Button(\\"跳转到B页面\\")\\n        .onClick(() => {\\n          router.pushUrl({\\n            url: \\"pages/Index2\\"\\n          })\\n        })\\n\\n      Button(\\"删除数据啦\\")\\n        .onClick(() => {\\n          AppStorageV2.remove(Person)\\n        })\\n\\n    }\\n  }\\n}\\n```\\n\\n如果此时执行了 `remove`方法，那么此时无论A页面中如何修改 `person`数据，`AppStorageV2` 中都不会跟随相应。B页面的`perosn`数据都不会受到影响。\\n\\n\\n\\n![PixPin_2024-08-08_00-05-31](readme.assets/PixPin_2024-08-08_00-05-31.gif)\\n\\n### keys\\n\\n返回所有`AppStorageV2`中的`key`\\n\\n**示例代码**\\n\\n```typescript\\n  Button(\\"返回AppStorageV2所有的keys\\")\\n    .onClick(() => {\\n      console.log(\\"AppStorageV2.keys()\\", AppStorageV2.keys())\\n    })\\n```\\n\\n\\n\\n\\n\\n## PersistenceV2\\n\\n`PersistenceV2`是应用级别的数据持久化技术，数据是直接存在设备磁盘上的，退出重新进入后，数据还存在\\n\\n`PersistenceV2`核心API和`AppStorageV2`类似，都提供了 `connect`、`remove`和`keys`。\\n\\n```typescript\\nimport { PersistenceV2 } from \'@kit.ArkUI\'\\n\\n\\n@ObservedV2\\nexport class Person {\\n  @Trace\\n  age: number = 10\\n}\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local person: Person = PersistenceV2.connect(Person, () => new Person)!\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Text(\\"A页面\\")\\n      // 预览器会失效\\n      Button(`年龄:${this.person.age}`)\\n        .onClick(() => {\\n          this.person.age++\\n        })\\n    }\\n  }\\n}\\n```\\n\\n![PixPin_2024-08-08_00-14-16](readme.assets/PixPin_2024-08-08_00-14-16.gif)\\n\\n\\n\\n---\\n\\n此时打开设备的文件目录，可以看到是实实在在把数据写到了磁盘中的。\\n\\n`/data/app/el2/100/base/com.example.你的包名/haps/entry/files/persistent_storage`\\n\\n![image-20240808003957736](readme.assets/image-20240808003957736.png)\\n\\n\\n\\n\\n\\n需要注意的是，`PersistenceV2`还有另外的两个API\\n\\n1. `save`  由于非`@Trace`的数据改变不会触发`PersistenceV2`的自动持久化，因此可以手动的调用`save`  进行持久化\\n2. `notifyOnError` 表示响应序列化或反序列化失败的回调 可以做错误处理\\n\\n\\n\\n\\n\\n### save  \\n\\n手动对@Trace的数据进行持久化\\n\\n| save   | 说明                                                         |\\n| ------ | ------------------------------------------------------------ |\\n| 参数   | keyOrType：需要手动持久化的key；如果指定的是type类型，key为type的name。 |\\n| 返回值 | 无。                                                         |\\n\\n**示例代码**：\\n\\n```typescript\\nimport { PersistenceV2 } from \'@kit.ArkUI\'\\n\\nexport class Person {\\n  age: number = 10\\n}\\n\\n@Entry\\n@ComponentV2\\nstruct Index {\\n  @Local person: Person = PersistenceV2.connect(Person, () => new Person)!\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Text(\\"A页面\\")\\n      // 预览器会失效\\n      Button(`年龄:${this.person.age}`)\\n        .onClick(() => {\\n          this.person.age++\\n          console.log(\\"this.person.age\\", this.person.age)\\n          PersistenceV2.save(Person)\\n        })\\n    }\\n  }\\n}\\n```\\n\\n---\\n\\n1. 首次打开页面，直接修改数据，此时发现UI不会刷新，但是 日志输出却显示 age再增加（因为没有了@`ObservedV2`和@`Trace`监听）\\n\\n2. 此时退出应用，重新打开，却发现age会变成上一次增加后的数据。因为每次修改后，都调用了`save`方法。已经把数据持久化到磁盘中了。当重新打开页面时，会重新执行 `  @Local person: Person = PersistenceV2.connect(Person, () => new Person)!`\\n\\n   代码，便从磁盘中读取出数据渲染到UI上\\n\\n\\n\\n### notifyOnError\\n\\n表示响应序列化或反序列化失败的回调 可以做错误处理\\n\\n| notifyOnError | 说明                                                         |\\n| ------------- | ------------------------------------------------------------ |\\n| 参数          | callback：当序列化或者反序列化失败时，执行该回调；若传入undefined，取消该回调。 |\\n| 返回值        | 无。                                                         |\\n\\n**示例代码**：\\n\\n```typescript\\n// 接受序列化失败的回调\\nPersistenceV2.notifyOnError((key: string, reason: string, msg: string) => {\\n  console.error(`error key: ${key}, reason: ${reason}, message: ${msg}`);\\n});\\n```\\n\\n\\n\\n\\n\\n### 序列化的补充\\n\\n如果要存储的数据是复杂类型嵌套的数据，需要使用  `@Type` 防止数据丢失\\n\\n```typescript\\nimport { PersistenceV2, Type } from \'@kit.ArkUI\'\\n\\nclass Son {\\n  weight: number = 100\\n}\\n\\nexport class Person {\\n  age: number = 10\\n  // 嵌套复杂类型，为了防止序列化数据失败，需要使用 @Type标记类型\\n  @Type(Son)\\n  son: Son = new Son()\\n}\\n```\\n\\n## 小结\\n\\n1. 如果考虑需要全局共享数据，那么可以考虑使用  `AppStorageV2`\\n2. 如果考虑数据需要持久化，那么可以使用 `PersistenceV2` ，因为是直接读写磁盘，所以不适合持久化大量数据，会导致应用性能下下降。"}'),d={name:"鸿蒙开发技巧/HarmonyOS Next V2 状态管理/HarmonyOS Next V2 AppStorageV2和PersistenceV2/AppStorageV2和PersistenceV2.md"};function o(c,s,g,y,b,F){return i(),a("div",null,[...s[0]||(s[0]=[e("",77)])])}const C=n(d,[["render",o]]);export{u as __pageData,C as default};
